function advance(direction){saveRunNote();const r=saved.activeRun;if(direction>0){r.events.push({step:r.index,title:r.steps[r.index].title,date:new Date().toISOString(),remaining:currentRemaining(),skippedTimer:currentRemaining()>0});}if(direction>0&&r.index===r.steps.length-1){const record={...r,complete:true,finishedAt:new Date().toISOString(),notes:Object.entries(r.stepNotes).filter(([,s])=>s.trim()).map(([i,t])=>`${r.steps[Number(i)].title}: ${t}`).join('\n\n')};saved.runs.push(record);saved.activeRun=null;persist();clearInterval(timerInterval);$('#app').innerHTML=`<div class="run-shell"><section class="panel run-card"><div class="finish-icon">${icon('check')}</div><p class="eyebrow">EXPERIMENTO REGISTRADO</p><h1>Protocolo completado</h1><p>${e(record.name)}</p><p class="help" style="margin-top:18px">Configuración, pasos, notas y horarios guardados en tu cuaderno.</p><div class="run-controls"><button class="button primary" data-nav="notebook">Ver registro</button><button class="button" data-report-run="${record.id}">Descargar / copiar para cuaderno</button></div></section></div>`;bindView();return;}r.index+=direction;r.timer={running:false,remaining:r.steps[r.index].seconds,deadline:null};persist();render();}
