function attachCommon(){ $$('[data-report-run]').forEach(b=>b.onclick=()=>exportExperiment(b.dataset.reportRun)); $$('[data-family]').forEach(b=>b.onclick=()=>chooseFamily(b.dataset.family,b.dataset.vendor||'')); $$('[data-export-data]').forEach(b=>b.onclick=()=>$('#backup').click());$$('[data-import-data]').forEach(b=>b.onclick=()=>$('#restore').click()); $$('[data-nav]').forEach(b=>b.onclick=()=>go(b.dataset.nav));$$('[data-protocol]').forEach(b=>b.onclick=()=>{state.detailTab=b.hasAttribute('data-notes-link')?'notes':'overview';location.hash='detail/'+b.dataset.protocol;});$$('[data-favorite]').forEach(b=>b.onclick=()=>{const prop=b.dataset.type==='media'?'mediaFavorites':'favorites',id=b.dataset.favorite;saved[prop]=saved[prop].includes(id)?saved[prop].filter(x=>x!==id):[...saved[prop],id];persist();render();});$$('[data-calc]').forEach(b=>b.onclick=()=>{state.calc=b.dataset.calc;if(state.page==='calculators')render();else go('calculators');});$$('[data-compound]').forEach(b=>b.onclick=()=>{state.compound=b.dataset.compound;state.calc='solutions';if(state.page==='calculators')render();else go('calculators');});$$('[data-compound-star]').forEach(b=>b.onclick=()=>{const id=b.dataset.compoundStar;saved.compoundFavorites=saved.compoundFavorites.filter(x=>x!==id);persist();render();});$$('[data-medium]').forEach(b=>b.onclick=()=>mediumDialog(b.dataset.medium));$$('[data-print]').forEach(b=>b.onclick=()=>window.print());$$('[data-export-run]').forEach(b=>b.onclick=()=>{const r=saved.runs.find(r=>r.id===b.dataset.exportRun);download('molab-registro-'+r.id+'.json',JSON.stringify(r,null,2));});if($('#new-protocol'))$('#new-protocol').onclick=()=>newProtocol();}
function bindView(){attachCommon();if(state.page==='sessions')bindSessions(personalSession,{render,toast,download});if($('#catalog-material'))$('#catalog-material').onchange=ev=>{state.material=ev.target.value;state.limit=48;render();};if($('#catalog-manufacturer'))$('#catalog-manufacturer').onchange=ev=>{state.manufacturer=ev.target.value;state.limit=48;render();};if($('#load-more'))$('#load-more').onclick=()=>{state.limit+=48;render();};if(state.page==='calculators'&&state.calc==='bench')bindTools(benchContext());if(state.page==='calculators'&&state.calc==='restriction')bindRestriction(restrictionContext());if(state.page==='protocols'){$$('[data-view]').forEach(b=>b.onclick=()=>{state.view=b.dataset.view;render();});$$('[data-category]').forEach(b=>b.onclick=()=>{state.category=b.dataset.category;state.limit=48;render();});$$('[data-origin]').forEach(b=>b.onclick=()=>{state.origin=b.dataset.origin;state.limit=48;render();});$('#protocol-search').oninput=ev=>{state.query=ev.target.value;state.limit=48;const pos=ev.target.selectionStart;render();$('#protocol-search').focus();$('#protocol-search').setSelectionRange(pos,pos);};}
 if(state.page==='detail'){const p=getProtocol();if(!p)return;if($('#protocol-version'))$('#protocol-version').onchange=ev=>{location.hash='detail/'+ev.target.value;};$$('[data-tab]').forEach(b=>b.onclick=()=>{state.detailTab=b.dataset.tab;render();});if($('#save-note'))$('#save-note').onclick=()=>{saved.notes[p.id]=$('#protocol-note').value;persist();toast('Notas guardadas.');};if($('#adapt-protocol'))$('#adapt-protocol').onclick=()=>newProtocol(p);if(state.detailTab==='config'){if(p.restrictionVendor){bindRestriction(restrictionContext());return;}if($('#save-personal-config'))$('#save-personal-config').onclick=()=>saveConfiguredProtocol(p);if($('#export-program'))$('#export-program').onclick=()=>exportProgram(p.title,clone(configFor(p)));const update=ev=>{let c=clone(configFor(p));if(ev.target.dataset.config==='volume'){const next=Number(ev.target.value);if(next>0&&c.volume>0){const factor=next/c.volume; c.components.forEach((r,i)=>{if(!r.template){r.volume=Math.round(r.volume*factor*100000)/100000;const input=document.querySelector(`[data-component="${i}"]`);if(input)input.value=r.volume;}});}}$$('[data-config]').forEach(x=>c[x.dataset.config]=Number(x.value));$$('[data-component]').forEach(x=>c.components[Number(x.dataset.component)].volume=Number(x.value));$$('[data-reagent]').forEach(x=>c.reagents[Number(x.dataset.reagent)].amount=Number(x.value));if($('[data-material]'))c.material=$('[data-material]').value;$$('[data-thermal]').forEach(x=>c.thermal[Number(x.dataset.thermal)][x.dataset.field]=x.dataset.field==='repeat'?x.checked:Number(x.value));c.edited=true;saved.configs[p.id]=c;persist();try{if($('[data-reagent-count]'))$('[data-reagent-count]').textContent=c.reactions;reagentAmounts(c.reagents).forEach((r,i)=>{const amount=$(`[data-reagent-amount="${i}"]`),total=$(`[data-reagent-total="${i}"]`);if(amount)amount.textContent=fmt(r.amount,4);if(total)total.textContent=r.measurement?'Medir cada muestra':fmt(r.amount*c.reactions,4)+' '+r.unit;});}catch(err){toast(err.message);}if($('#mix-result'))try{$('#mix-result').innerHTML=mixTable(masterMix(c,c.components));}catch(err){$('#mix-result').innerHTML=`<p class="error">${e(err.message)}</p>`;}if($('#thermal-chart'))$('#thermal-chart').innerHTML=thermalChart(c.thermal);if($('#thermal-duration'))$('#thermal-duration').textContent=thermalDescription(c);};$$('[data-config],[data-component],[data-thermal],[data-reagent],[data-material]').forEach(x=>x.oninput=update);$('#edit-steps').onclick=()=>editSteps(p);$('#add-thermal').onclick=()=>addThermal(p);$('#reset-config').onclick=()=>{delete saved.configs[p.id];persist();render();};$('#start-protocol').onclick=()=>startProtocol(p);if($('#export-mix'))$('#export-mix').onclick=()=>{try{const m=masterMix(configFor(p),configFor(p).components),csv=['Reactivo,Por tubo (uL),Total (uL),Destino',...m.rows.map(r=>`"${r.name.replace(/"/g,'""')}",${r.per},${r.total},${r.template?'Por tubo':'Mezcla comun'}`)].join('\r\n');download('molab-mastermix.csv','\uFEFF'+csv,'text/csv;charset=utf-8');}catch(err){toast(err.message);}};}}
 if(state.page==='calculators'&&!['bench','restriction'].includes(state.calc)){$$('#app input,#app select').forEach(x=>x.oninput=updateCalc);if($('#compound-select'))$('#compound-select').onchange=ev=>{state.compound=ev.target.value;render();};if($('#save-compound'))$('#save-compound').onclick=()=>{const id=$('#compound-select').value;saved.compoundFavorites=saved.compoundFavorites.includes(id)?saved.compoundFavorites.filter(x=>x!==id):[...saved.compoundFavorites,id];persist();render();};if($('#new-compound'))$('#new-compound').onclick=newCompound;if($('#update-compound'))$('#update-compound').onclick=()=>{try{const c=allCompounds().find(c=>c.id===state.compound);const mw=positive($('#mw').value,'Masa molecular');if(c.id.startsWith('compound-')){saved.customCompounds.find(x=>x.id===c.id).mw=mw;}else {const copy={...c,id:'compound-'+crypto.randomUUID(),name:c.name+' · personal',mw};saved.customCompounds.push(copy);saved.compoundFavorites.push(copy.id);state.compound=copy.id;}persist();render();toast('Masa molecular personal guardada.');}catch(err){toast(err.message);}};$$('[data-mix-protocol]').forEach(b=>b.onclick=()=>{state.detailTab='config';location.hash='detail/'+b.dataset.mixProtocol;});if($('#record-calc'))$('#record-calc').onclick=()=>{if(!lastCalc){toast('Revisa los valores antes de guardar.');return;}saved.runs.push({id:crypto.randomUUID(),kind:'calculation',name:lastCalc.title,date:new Date().toISOString(),input:clone(lastCalc.input),result:lastCalc.result+'\n'+lastCalc.description,calculator:lastCalc.kind});persist();toast('Cálculo guardado en el cuaderno.');};updateCalc();}
 if(state.page==='media'){$$('[data-media-category]').forEach(b=>b.onclick=()=>{state.mediaCategory=b.dataset.mediaCategory;render();});$('#media-search').oninput=ev=>{state.mediaQuery=ev.target.value;const pos=ev.target.selectionStart;render();$('#media-search').focus();$('#media-search').setSelectionRange(pos,pos);};}
 if(state.page==='run'&&saved.activeRun){if($('#run-program'))$('#run-program').onclick=()=>exportProgram(saved.activeRun.name,clone(saved.activeRun.config));if($('#edit-run-quantities'))$('#edit-run-quantities').onclick=editRunQuantities;$('#run-notes').oninput=saveRunNote;$('#save-exit').onclick=()=>{saveRunNote();go('notebook');};$('#previous-step').onclick=()=>advance(-1);$('#next-step').onclick=()=>advance(1);if($('#timer-toggle'))$('#timer-toggle').onclick=()=>{const r=saved.activeRun;if(r.timer.running)r.timer={running:false,remaining:currentRemaining(),deadline:null};else if(r.timer.remaining>0)r.timer={running:true,remaining:r.timer.remaining,deadline:Date.now()+r.timer.remaining*1000};persist();render();};if($('#timer-reset'))$('#timer-reset').onclick=()=>{saved.activeRun.timer={running:false,remaining:saved.activeRun.steps[saved.activeRun.index].seconds,deadline:null};persist();render();};}
}
$('#backup').onclick=()=>download('molab-copia-personal.json',JSON.stringify({format:'molab-v1',exportedAt:new Date().toISOString(),data:saved},null,2));
$('#restore').onchange=async ev=>{const file=ev.target.files[0];if(!file)return;try{if(file.size>5000000)throw new Error('La copia supera 5 MB.');const data=JSON.parse(await file.text());validateBackup(data);showDialog(`<h2>Importar copia personal</h2><p class="help">Se reemplazarán los datos locales de este navegador: favoritos, notas, protocolos personales y registros. Puedes exportar tus datos actuales antes de continuar.</p><div class="modal-footer"><button class="button" id="backup-current">Exportar datos actuales</button><button class="button primary" id="confirm-import">Importar copia</button></div>`);$('#backup-current').onclick=()=>$('#backup').click();$('#confirm-import').onclick=()=>{saved={...blank(),...data.data};persist();$('#modal').close();render();toast('Copia importada.');};}catch(err){toast('No se pudo importar: '+err.message);}ev.target.value='';};
function validateBackup(x){if(x.format!=='molab-v1')throw new Error('Formato no reconocido.');validatePersonal({...blank(),...x.data});}

document.addEventListener('keydown',ev=>{if((ev.ctrlKey||ev.metaKey)&&ev.key==='k'){ev.preventDefault();if(state.page!=='protocols'){location.hash='protocols';setTimeout(()=>$('#protocol-search')?.focus(),100);}else $('#protocol-search').focus();}});
initializeTheme();personalSession=new PersonalSession(sessionContext());window.addEventListener('hashchange',readRoute);readRoute();personalSession.start();
fetch('./catalog-index.json').then(r=>{if(!r.ok)throw new Error('Index not available');return r.json();}).then(data=>{indexReport=data;if(state.page==='sources')render();}).catch(()=>{});
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});

function addThermal(p){showDialog(`<h2>Añadir fase térmica</h2><form id="thermal-form"><div class="form-grid"><label class="field full">Nombre de la fase<input id="phase-label" required maxlength="80" value="Incubación"></label>${numberField('Temperatura (°C)','phase-temp',37,0)}${numberField('Duración (segundos)','phase-seconds',600,0)}<label class="checkbox-field full"><input id="phase-repeat" type="checkbox">Repetir en cada ciclo</label></div><div id="phase-error"></div><div class="modal-footer"><button class="button primary">Añadir fase</button></div></form>`);$('#thermal-form').onsubmit=ev=>{ev.preventDefault();try{const c=clone(configFor(p)),phase={label:$('#phase-label').value.trim(),temp:Number($('#phase-temp').value),seconds:Number($('#phase-seconds').value),repeat:$('#phase-repeat').checked};validateProgram([phase],c.cycles);c.thermal.push(phase);if(!c.steps.some(s=>s.title==='Termociclado'))c.steps.push({title:'Termociclado',text:'Ejecuta el programa térmico personalizado en el equipo.',conditions:'Programa personal',seconds:0});c.edited=true;saved.configs[p.id]=c;persist();$('#modal').close();render();}catch(err){$('#phase-error').innerHTML=`<p class="error">${e(err.message)}</p>`;}};}
